      "file": "rtl/sequence.sv",
      "content": "module TopModule(
	input clk,
	input rst_n,
	input a,
	output reg match
	);

	reg [7:0] a_tem;

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				match <= 1'b0;
			end
		else if (a_tem == 8'b01110001)
			begin
				match <= 1'b1;
			end
		else 
			begin	
				match <= 1'b0;
			end

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				a_tem <= 8'b0;
			end
		else 
			begin
				a_tem <= {a,a_tem[7:1]};
			end
endmodule"
    }
  ],
  "edit": "Changed match condition from 8'b01110000 to 8'b01110001 to match specification"
}

